¿Qué devuelve f(20)?

def f(n):
    s = 0
    for i in range(1, n + 1):
        if i % 3 == 0 or i % 5 == 0:
            s += i
    return s

¿Qué devuelve g([3, 1, 3, 2, 1, 3, 4])?

def g(xs):
    return sorted(set(xs), key=lambda x: (-xs.count(x), x))

¿Qué devuelve h("ab1c2")?

def h(s):
    r = ""
    for c in s:
        r = c + r if c.isalpha() else r + c
    return r

¿Qué devuelve sum(k(i) for i in range(8))?

def k(n):
    return n if n < 2 else k(n - 1) + k(n - 2)
